uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Simplex Noise Permutation
vec3 permute(vec3 x) { 
    return mod(((x * 34.0) + 1.0) * x, 289.0); 
}

// 2D Simplex Noise (Replaces the square-grid Value Noise)
// Eradicates straight-line artifacts completely
float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                       -0.577350269189626, 0.024390243902439);
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1;
    i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);
    vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
           + i.x + vec3(0.0, i1.x, 1.0));
    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
             dot(x12.zw,x12.zw)), 0.0);
    m = m * m;
    m = m * m;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    // Normalize to roughly [0, 1] range for FBM compatibility
    return (130.0 * dot(m, g)) * 0.5 + 0.5;
}

// Fractal Brownian Motion using Simplex Noise
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    mat2 shift = mat2(0.866, -0.5, 0.5, 0.866); 
    for (int i = 0; i < 4; i++) {
        v += a * snoise(p);
        p = shift * p * 2.0;
        a *= 0.5;
    }
    return v;
}

// Royal Blue & Gold Palette
vec3 palette(float t) {
    vec3 a = vec3(0.50, 0.40, 0.40); 
    vec3 b = vec3(0.50, 0.40, 0.40); 
    vec3 c = vec3(1.00, 1.00, 1.00); 
    vec3 d = vec3(0.00, 0.15, 0.45); 
    return a + b * cos(6.28318 * (c * t + d));
}

// Healing Neural Fog
float getHealingFog(vec2 uv, float t) {
    vec2 driftUV = uv * 3.0 + vec2(t * 0.1, t * -0.05);
    float n = fbm(driftUV);
    return smoothstep(0.4, 0.85, n);
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing
    float spd = (u_speed <= 0.0) ? 0.15 : u_speed * 0.5;
    float t = iTime * spd;

    // --- Background (Royal Blue Abyss) ---
    vec3 bgTop = vec3(0.0, 0.15, 0.5); 
    vec3 bgBottom = vec3(0.0, 0.02, 0.15); 

    // The 2Hz Delta pulse
    float deltaPulse = sin(iTime * 2.0 * spd) * 0.05; 
    bgTop += deltaPulse; 

    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5 + 0.1 * sin(t * 0.5));

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 4.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 1.0 : u_scale;
    float brightness = (u_intensity <= 0.0) ? 1.2 : u_intensity;

    for(float i = 0.0; i < 6.0; i++) {
        if(i >= density) break;

        // --- Cymatic Soundwave Distortion ---
        vec2 waveUV = uv0 * (1.0 + scale * 0.3);

        // Slow rotation
        waveUV *= rot(t * 0.05 + i * 1.2);

        // --- ORGANIC WANDERING & WARPING ---
        vec2 centerWander = vec2(
            sin(t * 0.15 + i * 2.1), 
            cos(t * 0.22 + i * 1.7)
        ) * 0.4;

        // Liquid domain warping using flawless Simplex FBM
        vec2 warp = vec2(
            fbm(waveUV * 2.0 + t * 0.1),
            fbm(waveUV * 2.0 - t * 0.15 + i)
        ) * 0.3;

        vec2 finalWaveUV = waveUV - centerWander + warp;

        // 528Hz healing frequencies
        float r = length(finalWaveUV);
        float harmonic = sin(r * 12.0 - t * 3.0 + i) * 0.5;

        harmonic += cos(finalWaveUV.x * 3.0 - t + i * 1.5) * 0.3;

        float dist = abs(harmonic - 0.1);

        // --- Gentle Sonic Glow ---
        float coreGlow = exp(-dist * 8.0) * 0.5; 
        float softGlow = exp(-dist * 2.0) * 0.3; 

        // --- Healing Fog Logic ---
        vec2 fogUV = finalWaveUV;
        fogUV.x += harmonic * 0.3; 

        float fogMap = getHealingFog(fogUV + vec2(i * 1.5, i * 2.5), t);

        float waveMask = exp(-dist * 1.5); 
        float fog = fogMap * waveMask * 1.5;

        // 4. Coloring
        float cycle = (u_color_cycle <= 0.0) ? 0.2 : u_color_cycle;
        vec3 col = palette(r * 0.3 + i * 0.2 + t * cycle);

        // Fog color: Brilliant, warm Gold
        vec3 fogCol = mix(col, vec3(1.0, 0.85, 0.2), 0.6);

        // Accumulate: Sonic Waves + Healing Fog
        finalColor += col * (coreGlow + softGlow) * brightness * 0.6;
        finalColor += fogCol * fog * brightness;
    }

    // 5. Post-Processing
    float vig = 1.0 - length(uv0) * 0.6;
    finalColor *= vig;

    // Smooth Tone Mapping
    finalColor = smoothstep(-0.1, 1.2, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
